const CASE_META={
ssa:{end:'-ssa/-ssä',q:'Missä?',en:r=>'in '+r.en,ne:r=>r.ne+'मा'},
sta:{end:'-sta/-stä',q:'Mistä?',en:r=>'from '+r.en,ne:r=>r.ne+'बाट'},
ill:{end:'-Vn',q:'Mihin?',en:r=>'into / to '+r.en,ne:r=>r.ne+' (तिर / भित्र)'},
lla:{end:'-lla/-llä',q:'Missä? / Kenellä?',en:r=>r.k==='person'?r.en+' has (with '+r.en+')':'on / at '+r.en,ne:r=>r.k==='person'?r.ne+'सँग':r.ne+'मा (माथि)'},
lta:{end:'-lta/-ltä',q:'Mistä? / Keneltä?',en:r=>'from '+r.en,ne:r=>r.ne+'बाट'},
lle:{end:'-lle',q:'Mihin? / Kenelle?',en:r=>r.k==='person'?'to '+r.en:'onto / to '+r.en,ne:r=>r.k==='person'?r.ne+'लाई':r.ne+'तिर / माथि'},
gen:{end:'-n',q:'Kenen? / Minkä?',en:r=>r.en+'\'s / of '+r.en,ne:r=>r.ne+'को'},
pl:{end:'-t',q:'—',en:r=>r.en+' (many)',ne:r=>r.ne+'हरू'}
};
